window.docContents[143].resolve({"/rules/PL1007/#PL1007-rationale":{"contents":"A contract is useful only if it constrains the code callers run. A registration over f n for a fixed parameter, or over an ineligible constant, says nothing about the executable definition across its domain.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1007: Executable contracts require supported closed evidence","header":"Why it matters","id":"/rules/PL1007/#PL1007-rationale"},"/rules/PL4004/#PL4004-rationale":{"contents":"Conforming claims reject compiler-trusting proofs (PL1004). A teaching fence is how the documentation shows one: it is classified and never counts as a conforming positive. A marker on an ordinary example would hide it from positive checking.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4004: Teaching examples require authenticated compiler classification","header":"Why it matters","id":"/rules/PL4004/#PL4004-rationale"},"/rules/PL5003/#PL5003-rationale":{"contents":"The explanation states what the formal statement says; the intent states what it is required to say. Comparing the two, and both with the declaration, exposes statements that are faithfully explained but wrong (standard §5.2).\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5003: Registered public material declarations require an Intent section","header":"Why it matters","id":"/rules/PL5003/#PL5003-rationale"}});